style.css:
@-moz-document domain("tradingview.com") {
html, body, #overlap-manager-root, .chart-container, .chart-container-inner, .layout__area--center, .chart-markup-table {
        background-image: url("https://giphy.com") !important;
        background-size: cover !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
        background-color: transparent !important;
    }
    .tv-side-toolbar, .top-properties-toolbar, .drawing-toolbar, .widgetbar-pages, .header-chart-panel {
        background-color: rgba(28, 32, 48, 0.5) !important;
    }
}
